[Razavikia2024Ring]
    Consider a communication network with $K$ nodes where the nodes use the encoder $\mathscr{E}_q$ in (7) and ML decoder $\mathscr{D}$ in (14) to compute the sum $f = \sum_{k}s_k$, where $s_k\in \mathbb{Z}$ over the noisy MAC with $\mathcal{CN}(0,\sigma^2)$. Assume that the constellation points induced by $\sum_{k}s_k$ have a uniform distribution over $\mathcal{Y}$. Then, the MSE of the function $f$ in Eq.~(4) becomes  
    \begin{align}

        \text{MSE}(f,\hat{f})  = \mu_1(d_1) + q^2\mu_2(d_2),
    \end{align}
    where
    \begin{align}

         \mu_1(x) =  2    \sum_{m=1}^{N_{1,K}-1}\alpha_{1,m}  Q\Big(\frac{(2m-1)x}{\sqrt{2}\sigma}\Big), \quad \mu_2(x) =  2    \sum_{m=1}^{N_{2,K}-1}\alpha_{2,m}  Q\Big(\frac{(2m-1)x}{\sqrt{2}\sigma}\Big),
    \end{align}
      and $\alpha_{1,m} := 2m -1 + \frac{3m(1-m)-1}{N_{1,K}}$, and $\alpha_{2,m} := 2m -1 + \frac{3m(1-m)-1}{N_{2,K}}$ with $N_{1,K}=K \times (q-1)+1$, $N_{2,K}=K \times (n-1)+1$, and $Q(x)$ is the Gaussian $Q$ function, i.e., 

\begin{align}
    Q(x)  = \frac{1}{\sqrt{2\pi}}\int_{x}^{\infty}{\rm e}^{-\frac{t^2}{2}}dt.
\end{align}

Consider the following polynomials:

    \begin{subequations}

       \begin{align}
   P^{(1)}_{N}(x)& := \sum_{m=1}^{N-1}\gamma_{m}{\rm e}^{-\theta_{m}x^{2}}\left(2\theta_{m}x^{2}+1\right), \\
      P^{(2)}_{N}(x) & := \frac{1}{x}\sum_{m=1}^{N-1}\gamma_{m}{\rm e}^{-\theta_{m}x^{2}}, 
   \end{align}
    \end{subequations}

    where we recall $\gamma_m = (2m-1)(2m-1+\frac{3m(1-m)-1}{N}), \theta_m=(2m-1)^2/4$ for all $m$.  Then, we have the following cases depending on the value of $N$: 
    \begin{enumerate}
       \item For $3 \leq N\leq 8$, the polynomial $P^{(1)}_{N}(x)$ has no positive real root. 
        \item  For $N = 9$, the polynomial $P^{(1)}_{N}(x)$ has two positive real roots at $\tilde{x}_1 = 9.6369\times 10^{-3}$ and $\bar{x}_1 = 0.2484$. 
        \item For $N\geq 10$,   both $P^{(1)}_{N}(x)$ and $P^{(2)}_{N}(x)$ each have a single positive real root.
    \end{enumerate}

Let $(x^*,y^*)$ denote a solution to (59). Then, the following statements hold:
    \begin{itemize}
        \item For $3 \leq N_{1,K}, N_{2,K} \leq 8$, there exists a single intersection between $g_q(x,y)$ and the ellipse constraint. 
        \item For $N_{1,K}~\text{or}~N_{2,K}\geq 9$, we define 

    \begin{align}

    \xi_1 := \begin{cases}  \frac{(q^2-1)\bar{x}_1^2}{12} + \frac{(n^2-1)\bar{y}_1^2}{12},&  N_{1, K}\geq 9, \\
        \frac{(q^2-1)\bar{x}_2^2}{12} + \frac{(n^2-1)\bar{y}_2^2}{12}, &  N_{1, K}\leq 8,~N_{2, K}\geq 10,
    \end{cases} \quad 
    \end{align}

    where $(x_1, y_1)$ and $(x_2, y_2)$ are positive roots of the following polynomials: 
\begin{subequations}
    \begin{align}
      & P_{N_{1,K}}^{(1)}(x_1) = 0,  \quad g_q(\bar{x}_1, \bar{y}_1) = 0, \\ 
      & P_{N_{2,K}}^{(1)}(y_2) = 0,  \quad g_q(\bar{x}_2, \bar{y}_2) = 0. 
\end{align}
\end{subequations}
                For $N_{1,K} = 9$ or $N_{2,K} = 9$, $\bar{x}_1$ and $\bar{y}_2$ are the largest positive root of $P^{(1)}_{9}(x)$ and $P^{(1)}_{9}(y)$, respectively. Then:
        \begin{itemize}
            \item For $\xi \geq \xi_1$, system~(59) admits multiple solutions, among which only the intersection corresponding to the middle branch of $g_q(x,y)$ yields the optimal solution.
            \item If $\xi \ll \xi_1$, all solutions to~(59) correspond to saddle points, and the optimal solutions lie on the boundary of the feasible region, i.e., at the intersections of the ellipse (power constraint) with the $x$- or $y$-axis.
        \end{itemize}
    \end{itemize}
